var toggle = document.getElementById('sort-toggle')
var list = document.getElementById('sort-list')
var label = document.getElementById('sort-label')
var options = document.querySelectorAll('.dd-option')

function openDropdown() {
  list.classList.add('open')
  toggle.setAttribute('aria-expanded', 'true')
  // Make first option focusable and focus it
  if (options.length > 0) {
    options[0].tabIndex = 0
    options[0].focus()
  }
}

function closeDropdown() {
  list.classList.remove('open')
  toggle.setAttribute('aria-expanded', 'false')
  // Reset all options to not be in tab order
  Array.prototype.forEach.call(options, function (option) {
    option.tabIndex = -1
  })
  toggle.focus()
}

toggle.addEventListener('click', function () {
  if (list.classList.contains('open')) {
    closeDropdown()
  } else {
    openDropdown()
  }
})

toggle.addEventListener('keydown', function (e) {
  if (e.key === 'Enter' || e.key === ' ') {
    e.preventDefault()
    if (list.classList.contains('open')) {
      closeDropdown()
    } else {
      openDropdown()
    }
  }
})

Array.prototype.forEach.call(options, function (option, index) {
  option.addEventListener('click', function () {
    label.textContent = 'Sort: ' + option.getAttribute('data-value')
    closeDropdown()
  })

  option.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault()
      label.textContent = 'Sort: ' + option.getAttribute('data-value')
      closeDropdown()
    } else if (e.key === 'ArrowDown') {
      e.preventDefault()
      var nextIndex = index + 1
      if (nextIndex < options.length) {
        options[nextIndex].tabIndex = 0
        options[nextIndex].focus()
        options[index].tabIndex = -1
      }
    } else if (e.key === 'ArrowUp') {
      e.preventDefault()
      var prevIndex = index - 1
      if (prevIndex >= 0) {
        options[prevIndex].tabIndex = 0
        options[prevIndex].focus()
        options[index].tabIndex = -1
      } else {
        // Move focus back to toggle on up arrow at first option
        closeDropdown()
      }
    } else if (e.key === 'Escape') {
      e.preventDefault()
      closeDropdown()
    }
  })
})

